//! `ips_image_relay`: per camera, subscribe to the two full-resolution iceoryx2
//! image streams (the camera's MONO8 `image` and the detector's RGB8
//! `debug_image`), downscale each frame with OpenCV, and republish it over zenoh
//! as protobuf `sensor_msgs/Image` for network peers that cannot read shared
//! memory. The binary in `main.rs` drives these modules.

// sb-generated iceoryx2 subscriber for `ros2/sensor_msgs/Image1280x1024`.
// Do not edit, `sb install .` regenerates it. Its baked default key is this
// module's own; `source` overrides `full` with the camera publisher's key.
#[path = "../swarmbotix_io/subscribers/image.rs"]
pub mod image_sub;

// sb-generated iceoryx2 subscriber for `ros2/sensor_msgs/Image1280x1024Color`.
// Do not edit. `source` overrides `full` with the detector's debug-image key.
#[path = "../swarmbotix_io/subscribers/debug_image.rs"]
pub mod debug_image_sub;

// sb-generated zenoh publisher for `ros2/sensor_msgs/Image` on topic `image`.
// Do not edit. Encoding is the caller's job; we feed it prost messages.
#[path = "../swarmbotix_io/publishers/image.rs"]
pub mod image_pub;

// sb-generated zenoh publisher for `ros2/sensor_msgs/Image` on topic `debug_image`.
// Do not edit.
#[path = "../swarmbotix_io/publishers/debug_image.rs"]
pub mod debug_image_pub;

/// prost types for the sb vault's `sensor_msgs/Image.proto` and its imports,
/// generated by build.rs. One module per protobuf package, side by side, so
/// the `super::std_msgs::Header` and `super::builtin_interfaces::Time` paths
/// prost writes resolve.
pub mod msgs {
    pub mod builtin_interfaces {
        include!(concat!(env!("OUT_DIR"), "/builtin_interfaces.rs"));
    }
    pub mod std_msgs {
        include!(concat!(env!("OUT_DIR"), "/std_msgs.rs"));
    }
    pub mod sensor_msgs {
        include!(concat!(env!("OUT_DIR"), "/sensor_msgs.rs"));
    }
}

pub mod rate;
pub mod relay;
pub mod scale;
pub mod source;
